var Bioptik=Bioptik||{},Bioptik={getDeviceSerial:function(address){sessionStorage["DeviceSerial_"+address]=address,WriteLog.write("設備序號："+address+"/"+sessionStorage["DeviceSerial_"+address],"info")},getPeripheralTime:function(address){sessionStorage["DeviceTime"+address]=WiseScripts.Format.Date_yyyyMMddHHmm(new Date),WriteLog.write("設備時間："+address+"/"+sessionStorage["DeviceTime"+address],"info")},a2hex:function(str,JoinDot){for(var arr=[],i=0,l=str.length;i<l;i++){var hex=Number(str.charCodeAt(i)).toString(16);arr.push(hex)}return JoinDot?arr.join(","):arr.join("")},StrToUint8Arr:function(str){for(var arr=new Uint8Array(str.length),i=0;i<str.length;i++)arr[i]=parseInt(Bioptik.a2hex(str.charAt(i)),16);return arr}};